import{_ as a,o as e,c as r,a2 as i}from"./chunks/framework.x7b91k6X.js";const u=JSON.parse('{"title":"漫画 · 第 10 话 企业级应用场景：行业与合规","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.10-enterprise-applications.md","filePath":"comics/EP.10-enterprise-applications.md","lastUpdated":1792677465000}'),o={name:"comics/EP.10-enterprise-applications.md"};function n(l,t,s,d,p,h){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="漫画-·-第-10-话-企业级应用场景-行业与合规" tabindex="-1">漫画 · 第 10 话 企业级应用场景：行业与合规 <a class="header-anchor" href="#漫画-·-第-10-话-企业级应用场景-行业与合规" aria-label="Permalink to &quot;漫画 · 第 10 话 企业级应用场景：行业与合规&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../10-enterprise-applications">10-enterprise-applications.md</a> ｜ 原画：<a href="./EP.10-enterprise-applications.svg">EP.10-enterprise-applications.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>斯威芙蒂</strong>：App Store 审核被拒 Guideline 5.1.1，金融版缺交易签名，医疗版不符合 HIPAA。</li><li><strong>Runtime 长老</strong>：教她把通用工程能力映射到具体行业的合规要求。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>通用 App 能上的架，行业 App 不一定能上。金融要交易签名和 SSL Pinning，医疗要数据加密和 HIPAA 合规，零售要高并发和离线队列。企业级开发的核心不是用更高级的框架，而是<strong>把每条法规条款映射成可验证的技术措施 + 证据留存</strong>，再配合量化的性能预算和企业 SSO/MDM 集成。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>行业 App 上架被拒的常见原因：</p><ul><li><strong>数据合规</strong>：未声明数据收集用途、隐私政策不完整（App Store Guideline 5.1.1）；</li><li><strong>金融行业</strong>：交易缺少客户端签名、通信未做证书绑定；</li><li><strong>医疗行业</strong>：健康数据未加密存储、不符合 HIPAA / GDPR 数据最小化原则。</li></ul><p>这些不是代码 bug，而是<strong>合规设计缺失</strong>，上线后补代价极大。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>行业特性映射表：</p><table tabindex="0"><thead><tr><th>行业</th><th>核心合规要求</th><th>技术措施</th></tr></thead><tbody><tr><td>金融</td><td>交易不可篡改、防中间人</td><td>RSA/ECDSA 签名、SSL Pinning、Keychain 存证书</td></tr><tr><td>医疗</td><td>数据隐私、访问审计</td><td>端到端加密、操作日志、最小权限</td></tr><tr><td>零售</td><td>高并发、弱网可用</td><td>离线队列、本地缓存、乐观同步</td></tr></tbody></table><p>企业集成三件套：</p><ul><li><strong>SSO（单点登录）</strong>：对接企业 IdP（Azure AD / Okta），一次登录访问所有系统；</li><li><strong>MDM（移动设备管理）</strong>：远程推送配置、强制密码策略、远程擦除；</li><li><strong>VPP（批量购买计划）</strong>：企业内部分发，不走 App Store 公开审核。</li></ul><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><ol><li><strong>性能预算量化</strong>：启动 ≤ 2s、列表 60fps、内存峰值 ≤ 200MB，超出预算即阻断发布（用 Instruments + MetricKit 持续监控）；</li><li><strong>合规逐条映射</strong>：把每条法规条款拆成「技术措施 + 验证方式 + 证据文档」，形成可追溯的合规矩阵，审计时直接导出；</li><li><strong>企业集成</strong>：SSO 统一登录、MDM 配置推送、VPP 内部分发，适配企业 IT 治理。</li></ol><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><ol><li>行业差异在合规：金融要签名、医疗要加密、零售要高并发与离线。</li><li>性能预算量化到指标（启动/帧率/内存），超预算即阻断发布。</li><li>合规逐条映射到技术措施+证据，审计时可追溯、可导出。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：金融 App 的交易签名为什么必须在客户端做，不能只靠 HTTPS？</p><p><strong>答</strong>：HTTPS 只保证「传输链路不被窃听/篡改」，但不保证「请求内容是用户真实意图」。如果攻击者拿到用户的 session（比如 XSS 窃取 cookie），可以用 HTTPS 正常发请求，但内容是攻击者伪造的。交易签名要求用户对交易内容（金额、收款人）用私钥签名，服务端验签后确认是用户本人操作，即使 session 被窃也无法伪造。私钥存在 Keychain 且绑定 Secure Enclave，无法导出。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><p>运行 <code>swift run EnterprisePatterns</code>，查看 <code>OfflineQueue.swift</code>（离线队列）和 <code>ManagedConfig.swift</code>（MDM 配置）的实现；阅读第 10 章的合规映射矩阵模板和性能预算制定方法。</p><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>行业合规搞定了，可页面越来越复杂，MVC 胖控制器、MVVM 状态散、TCA 学不会。第 11 话《架构：MVC/MVVM/TCA 选型》，给复杂 App 找一套能落地的架构。</p>',27)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
